/* @autogenerated */
import { Observable } from 'rxjs';

/** Trozo de texto con formato dentro de un bloque. */
export interface Run {
  text: string;
  bold?: boolean;
  italic?: boolean;
  strike?: boolean;
  code?: boolean;
  /** Destino del enlace, si lo es. */
  link?: string;
  /** Salto de línea dentro del bloque (en lugar de texto). */
  break?: boolean;
}

export type Align = 'left' | 'center' | 'right' | null;

/**
 * Bloque del documento: el subconjunto de Markdown que saben escribir todos los formatos. Es el modelo intermedio
 * entre el Markdown ya rellenado y cada formato de salida (Word, PDF).
 */
export type Block =
  | { kind: 'heading'; level: number; runs: Run[] }
  | { kind: 'paragraph'; runs: Run[] }
  | { kind: 'list'; ordered: boolean; start: number; items: Block[][] }
  | { kind: 'table'; header: Run[][]; rows: Run[][][]; align: Align[] }
  | { kind: 'code'; text: string }
  | { kind: 'quote'; blocks: Block[] }
  | { kind: 'rule' }
  | { kind: 'pagebreak' };

export type DocumentFormat = 'docx' | 'pdf';

/**
 * Documento a generar desde una plantilla Markdown de `public/templates/`.
 *
 * `template` es la ruta sin extensión (`installations/project/report`): se busca primero la variante del idioma
 * activo (`report.es-ES.md`, `report.es.md`) y después `report.md`. `data` aporta el contexto con el que se rellena
 * (normalmente un `resolve` del repositorio, con sus referencias e hijos).
 */
export interface DocumentDefinition<T> {
  template: string;
  data: (item: T) => Observable<unknown>;
  /** Nombre del fichero, sin extensión. */
  fileName: (item: T) => string;
  /** Formatos que se ofrecen; por defecto los dos. */
  formats?: DocumentFormat[];
}
